"""Render README evaluation claims and the held-out threshold curve from results.json."""
import json
from pathlib import Path
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

r=json.loads(Path('results.json').read_text())
def pct(x): return 'n/a' if x is None else f'{100*x:.2f}%'
def metric(m,k):
    ci=m.get('ci95',{}).get(k)
    return pct(m[k])+(f' [{pct(ci[0])}, {pct(ci[1])}]' if ci else '')
def table_metric(m): return f"{pct(m['recall'])} / {pct(m['fpr'])}"

v1=r['v1_vs_v2']['v1_seed_b'];v2=r['v1_vs_v2']['v2_seed_c']
lines=['<!-- Generated by scripts/report.py from results.json. -->','## Held-out evaluation (v2)','',
f"Seed A selected the ratio threshold and factory queue rule once. Fresh seed C ({r['dataset']['factories']:,} factories × 12 months) reports the results below; fake benign explanations for C cheats are retained only in external truth data. The monthly SQL rule remains two independent source families. Threshold: {r['protocol']['threshold']}; factory queue K: {r['factory_queue']['k']}.",'',
'### v1 versus v2','','| Evaluation | Unit | Recall | FPR | TP | FP | FN | TN |','|---|---|---:|---:|---:|---:|---:|---:|']
for label,record in [('v1 seed B',v1),('v2 seed C',v2)]:
    for unit in ('factory_month','factory'):
        m=record[unit];lines.append(f"| {label} | {unit} | {pct(m['recall'])} | {pct(m['fpr'])} | {m['tp']} | {m['fp']} | {m['fn']} | {m['tn']} |")
lines += ['', 'v1 is retained for comparison. v2 is the current held-out evaluation. Both are synthetic scenario recovery, not estimates of deployment accuracy.', '',
'### v2 metrics and queue','','| Unit | TP | FP | FN | TN | Recall [95% CI] | FPR [95% CI] |','|---|---:|---:|---:|---:|---|---|']
for unit in ('factory_month','factory'):
    m=r[unit];lines.append(f"| {unit} | {m['tp']} | {m['fp']} | {m['fn']} | {m['tn']} | {metric(m,'recall')} | {metric(m,'fpr')} |")
lines += ['',f"A factory enters the weekly review queue after {r['factory_queue']['k']} prioritised months. On seed C it contains {r['factory_queue']['queue_size']:,} factories; its recall/FPR are {table_metric(r['factory_queue']['seed_c'])}. K candidates and seed-A calibration are recorded in `results.json`.",'',
'### Recall by cheat type and intensity','','| Type / intensity | Factory-month recall [95% CI] | Factory recall [95% CI] |','|---|---|---|']
for key,m in r['recall_by_type_intensity']['factory_month'].items(): lines.append(f"| {key} | {metric(m,'recall')} | {metric(r['recall_by_type_intensity']['factory'][key],'recall')} |")
lines += ['', '### False positives: clean factories, decoys and evidence pairs', '', '| Negative group | Factory-month FPR | Factory FPR |','|---|---|---|']
for name,m in r['fpr_clean_vs_decoy']['factory_month'].items(): lines.append(f"| {name.replace('_',' ')} | {metric(m,'fpr')} | {metric(r['fpr_clean_vs_decoy']['factory'][name],'fpr')} |")
lines += ['', '| Decoy | Factory-month FPR | Factory FPR |','|---|---|---|']
for name,m in r['fpr_by_decoy']['factory_month'].items(): lines.append(f"| {name.replace('_',' ')} | {metric(m,'fpr')} | {metric(r['fpr_by_decoy']['factory'][name],'fpr')} |")
lines += ['', '| Decoy / fired source families | Months | False positives | FPR |','|---|---:|---:|---:|']
for x in r['decoy_signal_pairs']: lines.append(f"| {x['scenario'].replace('_',' ')} / {x['signal_pair']} | {x['months']} | {x['false_positives']} | {pct(x['fpr'])} |")
lines += ['',f"{r['single_signal_decoy_months']:,} honest decoy months fired exactly one source family. They are not prioritised; a disposition can mark documented operating changes as cleared or leave them review-only.",'',
'### Ranking and review capacity','','The predeclared sort key is: number of source families firing, then weakest-link normalised gap, then value-at-risk proxy. Ranking variants were compared on seed A only; v2 reports seed C. Value at risk is the largest evidence gap monetised with the synthetic per-kg amount, or the bank amount itself; it is an ordering proxy, not a tax assessment.','','| If you can review K cases per snapshot | Observed seed-C synthetic precision |','|---:|---:|']
for x in r['review_capacity']['capacity_rows']: lines.append(f"| {x['cases_per_snapshot']} | {pct(x['precision'])} |")
lines += ['', '| Seed-A sort test (top 50) | Mean precision |','|---|---:|']
for name,x in r['ranking']['seed_a_sort_test'].items(): lines.append(f"| {name.replace('_',' ')} | {pct(x['macro_precision'])} |")
lines += ['', '### Prevalence-adjusted precision', '', 'These are illustrative recalculations using the held-out sensitivity and FPR. They do not assert fraud prevalence in any real population.', '', '| Assumed cheat prevalence | Precision |','|---|---:|']
for label,x in r['prevalence_adjusted_precision'].items(): lines.append(f"| {label} | {pct(x['precision'])} |")
lines += ['', '### Robustness sweep', '', r.get('robustness',{}).get('protocol','Not run.'), '', '| Variant | Monthly recall | Monthly FPR | Factory queue size |','|---|---:|---:|---:|']
for name,x in r.get('robustness',{}).get('variants',{}).items(): lines.append(f"| {name.replace('_',' ')} | {pct(x['factory_month']['recall'])} | {pct(x['factory_month']['fpr'])} | {x['factory_queue']['queue_size']} |")
lines += ['', '### Discrepancy classification', '', 'Rows are truth and columns are evidence classifications. The strongest non-financial signal determines the class; `no signal` is abstention. Classes describe evidence, not guilt.', '', '| Truth | '+' | '.join(r['confusion']['columns_predicted'])+' |','|---|'+'---:|'*6]
for label,values in zip(r['confusion']['rows_truth'],r['confusion']['counts']): lines.append('| '+label+' | '+' | '.join(map(str,values))+' |')
lines += ['', '### Misses and limits', '', f"Missed {r['misses']['factory_months']:,} active cheat months; {r['misses']['factories_never_caught']:,} cheat factories did not enter the K-month factory queue. Full rows and reasons: [misses.csv](reports/misses.csv).", '', '| Factory | Month | Scenario | Intensity | Signals | Reason |','|---|---|---|---:|---:|---|']
for x in r['misses']['examples'][:5]: lines.append(f"| {x['factory_id']} | {x['period_month']} | {x['scenario']} | {pct(x['intensity'])} | {x['signals']} | {x['reason']} |")
lines += ['', '![Held-out recall vs false-positive rate](reports/recall_fpr.png)', '', 'The curve is diagnostic on seed C and did not select the threshold. A, B and C share a deliberately limited generator. Synthetic data does not establish real-world accuracy, causal independence or legal sufficiency. Every case needs human review; access to power and bank data requires lawful authorisation and privacy safeguards.']
text='\n'.join(lines)+'\n';Path('reports/evaluation.md').write_text(text)
readme=Path('README.md').read_text();start,tail=readme.split('<!-- EVALUATION START -->',1);_,tail=tail.split('<!-- EVALUATION END -->',1)
Path('README.md').write_text(start+'<!-- EVALUATION START -->\n'+text+'<!-- EVALUATION END -->'+tail)
curve=r['threshold_curve'];fig,ax=plt.subplots(figsize=(7.5,4.5));ax.plot([x['fpr']*100 for x in curve],[x['recall']*100 for x in curve],'o-',color='#156b68')
chosen=next(x for x in curve if x['threshold']==r['protocol']['threshold']);ax.scatter([chosen['fpr']*100],[chosen['recall']*100],s=100,color='#bd4b30',label=f"A-selected threshold {chosen['threshold']}",zorder=3)
ax.set(xlabel='Seed-C factory-month false-positive rate (%)',ylabel='Seed-C recall (%)',title='Threshold sensitivity on seed C (not used for tuning)');ax.grid(alpha=.2);ax.legend();fig.tight_layout();fig.savefig('reports/recall_fpr.png',dpi=160);plt.close(fig)
summary={'factory_month_recall':pct(r['factory_month']['recall']),'factory_month_fpr':pct(r['factory_month']['fpr']),'factory_recall':pct(r['factory']['recall']),'factory_fpr':pct(r['factory']['fpr']),'misses':r['misses']['factory_months'],'factories':r['dataset']['factories'],'raw_evidence_rows':r['dataset']['raw_evidence_rows'],'single_signal_decoys':r['single_signal_decoy_months'],'queue_k':r['factory_queue']['k']}
Path('reports/presentation_metrics.json').write_text(json.dumps(summary,indent=2)+'\n')
